<div><form wire:submit="save"><input wire:model="vendor_name" placeholder="Vendor"><input wire:model="evaluation_date" type="date"><input wire:model="quality_rating" type="number" min="0" max="5"><input wire:model="timeliness_rating" type="number" min="0" max="5"><input wire:model="communication_rating" type="number" min="0" max="5"><input wire:model="cost_effectiveness_rating" type="number" min="0" max="5"><input wire:model="professionalism_rating" type="number" min="0" max="5"><button type="submit">{{ $editingEvaluationId === null ? 'Save evaluation' : 'Update evaluation' }}</button>@if ($editingEvaluationId !== null)<button type="button" wire:click="cancelEdit">Cancel</button>@endif</form><ul>@forelse($evaluations as $evaluation)<li>{{ $evaluation->vendor_name }} — {{ $evaluation->overall_rating }}/5 ({{ $evaluation->evaluation_date }}) <button type="button" wire:click="edit({{ $evaluation->id }})">Edit</button> <button type="button" wire:click="delete({{ $evaluation->id }})">Delete</button></li>@empty<li>No vendor evaluations yet.</li>@endforelse</ul></div>
